// Fail-closed: senza segreto configurato non passa niente.
// Un webhook n8n attivo è un URL pubblico: chiunque lo conosca può scriverci
// dentro. Questa è la sola cosa che sta fra il tuo foglio e il mondo.
let secret;
try { secret = $env.LEAD_WEBHOOK_SECRET; } catch (e) {}
if (!secret) { try { secret = $vars.LEAD_WEBHOOK_SECRET; } catch (e) {} }
if (!secret) {
  throw new Error(
    'Set LEAD_WEBHOOK_SECRET first: an environment variable when self-hosted, ' +
    'or Settings → Variables on n8n Cloud. Until then every request is refused.'
  );
}

const out = [];
for (const item of $input.all()) {
  const headers = item.json.headers || {};
  // I nomi degli header arrivano già in minuscolo, ma non su ogni proxy.
  const chiave = String(
    headers['x-webhook-key'] ?? headers['X-Webhook-Key'] ?? ''
  );
  // Il confronto non esce al primo carattere sbagliato: percorre comunque
  // tutta la chiave ricevuta. Non è una garanzia di tempo costante — in
  // JavaScript non si può promettere, il JIT fa quello che vuole — ma toglie
  // il segnale più grossolano. Se il tuo n8n può usarla, l'autenticazione
  // header nativa del nodo Webhook è la scelta migliore.
  const atteso = String(secret);
  let diverso = chiave.length === atteso.length ? 0 : 1;
  for (let i = 0; i < chiave.length; i++) {
    if (chiave.charCodeAt(i) !== atteso.charCodeAt(i)) diverso |= 1;
  }
  if (diverso) throw new Error('Refused: missing or wrong x-webhook-key header');
  out.push(item);
}
return out;

// Quello che arriva davvero in un form pubblico: bot che riempiono ogni
// campo, indirizzi usa-e-getta, messaggi di due caratteri, muri di link.
// Qui non si butta niente in silenzio: ogni scarto esce con il motivo scritto.

const MIN_MESSAGGIO = 15;      // caratteri sotto i quali un messaggio non dice nulla
const MAX_LINK = 2;            // link in un primo contatto: oltre, è pubblicità
const USA_E_GETTA = [
  'mailinator.com', 'guerrillamail.com', 'yopmail.com', '10minutemail.com',
  'tempmail.com', 'trashmail.com', 'sharklasers.com', 'getnada.com',
  'temp-mail.org', 'dispostable.com', 'maildrop.cc', 'fakeinbox.com',
];
// I nomi del campo trappola. NON usare `website`: moltissimi form ne hanno uno
// vero («il tuo sito»), e chi lo compila sarebbe scartato per sempre.
const TRAPPOLE = ['_gotcha', 'hp_field', 'nickname_confirm'];
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const out = [];
for (const item of $input.all()) {
  const raw = item.json.body ?? item.json;
  const email = String(raw.email ?? '').trim().toLowerCase();
  const messaggio = String(raw.message ?? raw.comments ?? '').trim();
  const dominio = email.includes('@') ? email.split('@').pop() : '';
  const cifreTel = String(raw.phone ?? raw.telephone ?? '').replace(/[^0-9]/g, '');
  const raggiungibile = EMAIL_RE.test(email) || cifreTel.length >= 7;
  // Maiuscole comprese: «HTTPS://» conta come link quanto «https://».
  const link = (messaggio.match(/https?:\/\//gi) || []).length;

  const motivi = [];
  if (TRAPPOLE.some((c) => String(raw[c] ?? '').trim() !== '')) motivi.push('honeypot field was filled in');

  // Un modo per richiamare deve esserci. Ma il telefono basta: un form che
  // chiede solo il numero è normale, e scartare quel lead sarebbe un errore
  // che nessuno vedrebbe mai.
  if (!raggiungibile) motivi.push('no usable email address and no phone number');

  // Sottodomini compresi: mail.tempmail.com è tempmail.com.
  if (dominio && USA_E_GETTA.some((d) => dominio === d || dominio.endsWith('.' + d))) {
    motivi.push('disposable email domain: ' + dominio);
  }

  // «Call me» è corto ma non è spazzatura, se ha lasciato un numero.
  if (messaggio.length > 0 && messaggio.length < MIN_MESSAGGIO && cifreTel.length < 7) {
    motivi.push('message is too short to act on, and no phone number');
  }

  if (link > MAX_LINK) motivi.push(link + ' links in a first message');

  out.push({ json: { ...raw, junk: motivi.length > 0, junk_reason: motivi.join('; '),
                     received_at: new Date().toISOString() } });
}
return out;

// Il ramo dello scarto scrive comunque su un foglio, quindi passa dalla stessa
// protezione del ramo buono: lo spam è proprio il posto dove una formula ha più
// probabilità di essere stata messa apposta.
// Si tengono tre campi soltanto: di un bot non serve conservare l'intero corpo.
const pericoloso = /^[=+\-@\t\r]/;
const sicuro = (v) => (typeof v === 'string' && pericoloso.test(v) ? "'" + v : v);

return $input.all().map((item) => ({ json: {
  received_at: item.json.received_at,
  email: sicuro(String(item.json.email ?? '').slice(0, 200)),
  reason: sicuro(String(item.json.junk_reason ?? '')),
} }));

// La stessa persona scrive «MARIA rossi», « Maria Rossi » e «maria rossi».
// Senza questo passaggio il foglio diventa illeggibile in due settimane.

const PAESE_PREDEFINITO = '+39';   // prefisso da mettere ai numeri senza indicatore

// Lo «zero di tronco» iniziale: in Italia fa parte del numero (+1234567890),
// nel Regno Unito e in Francia va tolto (+44 20 ..., non +44 020 ...). Non
// esiste una regola universale, quindi non si indovina: si dichiara. Il valore
// predefinito segue PAESE_PREDEFINITO qui sopra.
const TOGLI_ZERO_INIZIALE = false;
const MAIL_GRATUITE = [
  'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com',
  'icloud.com', 'aol.com', 'gmx.com', 'proton.me', 'protonmail.com', 'mail.com',
];

const maiuscola = (s) => s.charAt(0).toUpperCase() + s.slice(1);

// «de rossi», «o'brien», «anna-maria» devono restare leggibili.
const nomeProprio = (s) => s
  .toLowerCase()
  .split(/(\s+|-|')/)
  .map((p) => (/^[\s\-']+$/.test(p) ? p : maiuscola(p)))
  .join('');

const out = [];
for (const item of $input.all()) {
  const raw = item.json;
  const email = String(raw.email ?? '').trim().toLowerCase();
  const dominio = email.includes('@') ? email.split('@').pop() : '';

  const intero = String(raw.name ?? raw.full_name ?? '').trim();
  const pezzi = intero.split(/\s+/).filter(Boolean);

  // Telefono. Tre forme arrivano davvero: «+39 02 …», «0039 02 …» e «02 …».
  // Le prime due sono già internazionali e non vanno toccate; solo la terza
  // prende il prefisso. Un'estensione («… int. 12») allunga il numero fino a
  // renderlo impossibile, quindi vale il tetto E.164 di 15 cifre.
  const grezzo = String(raw.phone ?? raw.telephone ?? '').trim();
  const cifre = grezzo.replace(/[^0-9]/g, '');
  const giaInternazionale = grezzo.startsWith('+') || cifre.startsWith('00');
  let telefono = '';
  if (cifre.length >= 7) {
    let finale;
    if (giaInternazionale) {
      finale = cifre.replace(/^00/, '');            // 0039… → 39…
    } else {
      finale = PAESE_PREDEFINITO.replace('+', '')
             + (TOGLI_ZERO_INIZIALE ? cifre.replace(/^0+/, '') : cifre);
    }
    telefono = finale.length <= 15 ? '+' + finale : '';
  }

  const aziendale = Boolean(dominio) && !MAIL_GRATUITE.includes(dominio);

  out.push({ json: {
    first_name: pezzi[0] ? nomeProprio(pezzi[0]) : '',
    last_name: pezzi.slice(1).map(nomeProprio).join(' '),
    email,
    phone: telefono,
    company_domain: aziendale ? dominio : '',
    business_email: aziendale,
    message: String(raw.message ?? raw.comments ?? '').replace(/\s+/g, ' ').trim(),
    source: String(raw.source ?? raw.utm_source ?? 'web form').trim(),
    received_at: raw.received_at ?? new Date().toISOString(),
  } });
}
return out;

// Un foglio di calcolo esegue quello che comincia per = + - @, perché il nodo
// Sheets scrive in modalità USER_ENTERED: la cella viene interpretata come se
// l'avessi digitata tu. «=HYPERLINK(...)» dentro il campo nome diventa un link
// cliccabile nel foglio di chi legge i lead. Nessuno lo controlla, perché «è
// solo un form».
const pericoloso = /^[=+\-@\t\r]/;

// Ricorsivo: un form può mandare oggetti annidati e liste, e proteggere solo il
// primo livello lascia passare esattamente i casi che nessuno guarda.
function ripulisci(v) {
  if (typeof v === 'string') return pericoloso.test(v) ? "'" + v : v;
  if (Array.isArray(v)) return v.map(ripulisci);
  if (v && typeof v === 'object') {
    const o = {};
    for (const [k, x] of Object.entries(v)) o[k] = ripulisci(x);
    return o;
  }
  return v;
}

return $input.all().map((item) => ({ json: ripulisci(item.json) }));
